              className="text-slate-600 hover:text-brand-600 p-2 bg-slate-100 rounded-full"
            >
              {isOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu Dropdown */}
      {isOpen && (
        <div className="md:hidden bg-white border-t border-slate-100 absolute w-full shadow-xl rounded-b-3xl">
          <div className="px-6 pt-4 pb-8 space-y-2">
            {navLinks.map((link) => (
              <a
                key={link.name}
                href={link.href}
                className={`block px-4 py-3 rounded-2xl text-base font-medium transition-colors ${
                    // @ts-ignore
                    link.highlight 
                    ? 'text-brand-600 bg-brand-50 font-bold'
                    : 'text-slate-700 hover:text-brand-600 hover:bg-brand-50'
                }`}
                onClick={(e) => {
                    setIsOpen(false);
                    // @ts-ignore
                    handleNavClick(e, link.name, link.view);
                }}
              >
                {/* @ts-ignore */}
                {link.highlight && <span className="inline-block mr-2 text-xs bg-rose-500 text-white px-1.5 rounded">免费</span>}
                {link.name}
              </a>
            ))}

            {!isAuthenticated && (
                <div className="mt-4 pt-4 border-t border-slate-100 flex flex-col space-y-3">
                <button 
                    onClick={() => {
                    setIsOpen(false);
                    setIsLoginOpen(true);
                    }}
                    className="w-full text-center py-3 border-2 border-slate-200 rounded-xl text-slate-600 font-bold"
                >
                    登录
                </button>
                <button 
                    onClick={() => {
                        setIsOpen(false);
                        setIsLoginOpen(true);
                    }}
                    className="w-full text-center py-3 bg-slate-900 text-white rounded-xl font-bold shadow-lg"
                >
                    立即注册
                </button>
                </div>
            )}

            {isAuthenticated && (
                 <button 
                 onClick={() => {
                     logout();
                     setIsOpen(false);
                     onNavigate('home');
                 }}
                 className="w-full text-center py-3 bg-slate-100 text-slate-600 rounded-xl font-bold mt-4"
             >
                 退出登录
             </button>
            )}
          </div>
        </div>
      )}
    </header>

    {/* Login Modal */}
    <LoginModal isOpen={isLoginOpen} onClose={() => setIsLoginOpen(false)} onSuccess={() => onNavigate('learning-center')} />
    </>
  );
};

import React, { useState, useEffect } from 'react';
import { X, User, Lock, Smartphone, ShieldCheck, QrCode, Monitor, ChevronRight, AlertCircle } from 'lucide-react';
import { Logo } from './Logo';
import { useAuth } from '../context/AuthContext';

interface LoginModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess?: () => void;
}

type LoginMethod = 'password' | 'sms';

export const LoginModal: React.FC<LoginModalProps> = ({ isOpen, onClose, onSuccess }) => {
  const [method, setMethod] = useState<LoginMethod>('password');
  const [isQrMode, setIsQrMode] = useState(false);
  const [agreed, setAgreed] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);

  // Login State
  const [account, setAccount] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const { login } = useAuth();

  // Prevent scrolling when modal is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
      setError('');
      setAccount('');
      setPassword('');
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  const handleLogin = () => {
      if (!account || !password) {
          setError('请输入账号和密码');
          return;
      }
      if (!agreed) {
          setError('请先阅读并同意用户协议');
          return;
      }

      setIsLoading(true);
      setError('');

      // Simulate network request
      setTimeout(() => {
          if (account === '17549531024' && password === '1234@qwer') {
              login(account); // Call context login
              setIsLoading(false);
              onClose();
              if (onSuccess) onSuccess();
          } else {
              setError('账号或密码错误');
              setIsLoading(false);
          }
      }, 800);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center px-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity"
        onClick={onClose}
      ></div>

      {/* Modal Card */}
      <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-[420px] relative overflow-hidden animate-scale-in">

        {/* Close Button */}
        <button 
          onClick={onClose}
          className="absolute top-4 left-4 p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors z-20"
        >
          <X size={20} />
        </button>

        {/* QR / PC Switcher (Corner Ribbon) */}
        <div 
            className="absolute top-0 right-0 cursor-pointer z-20 group"
            onClick={() => setIsQrMode(!isQrMode)}
        >
            {/* The triangular background */}
            <div className="w-20 h-20 bg-gradient-to-bl from-brand-50 via-slate-50 to-white absolute top-0 right-0 clip-triangle shadow-sm border-b border-l border-slate-100 group-hover:from-brand-100 transition-colors"></div>
            {/* The Icon */}
            <div className="absolute top-3 right-3 text-brand-500">
                {isQrMode ? <Monitor size={28} /> : <QrCode size={28} />}
            </div>
            {/* Tooltip */}
            <div className="absolute top-4 right-14 bg-slate-800 text-white text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
                {isQrMode ? '账号登录' : '扫码登录'}
            </div>
        </div>

        {/* Content Area */}
        <div className="p-8 pt-12">

            {/* Header Logo */}
            <div className="flex justify-center mb-8">
                <Logo withText />
            </div>

            {isQrMode ? (
                // QR Code View
                <div className="flex flex-col items-center py-4 animate-fade-in">
                    <h3 className="text-xl font-bold text-slate-800 mb-2">微信扫码登录</h3>
                    <p className="text-slate-400 text-sm mb-6">安全快捷 · 无需输入</p>

                    <div className="w-48 h-48 border border-slate-100 rounded-2xl p-2 mb-6 shadow-inner bg-slate-50 flex items-center justify-center relative group cursor-pointer">
                        {/* Mock QR Code */}
                        <div className="w-full h-full bg-white rounded-xl flex items-center justify-center overflow-hidden">
                             <img src="https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=MoguoYunkeLogin" alt="QR Code" className="opacity-80 group-hover:opacity-100 transition-opacity" />
                        </div>
                        {/* Scan Overlay */}
                        <div className="absolute inset-0 bg-white/60 backdrop-blur-[2px] flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity rounded-2xl">
                            <div className="bg-brand-500 text-white p-3 rounded-full shadow-lg">
