import React, { useState } from 'react';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { CategorySection } from './components/CategorySection';
import { RecommendedCourses } from './components/RecommendedCourses';
import { RecommendedInstitutions } from './components/RecommendedInstitutions';
import { Footer } from './components/Footer';
import { FloatingSidebar } from './components/FloatingSidebar';
import { LearningCenter } from './components/LearningCenter';
import { SearchResults } from './components/SearchResults';
import { AuthProvider } from './context/AuthContext';

type View = 'home' | 'learning-center' | 'search-results';

const AppContent: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('home');
  const [searchQuery, setSearchQuery] = useState('');

  const handleSearch = (query: string) => {
    setSearchQuery(query);
    setCurrentView('search-results');
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  return (
    <div className="min-h-screen flex flex-col relative bg-slate-50">
      {/* Sticky Header */}
      <Navbar 
        onNavigate={setCurrentView} 
        currentView={currentView} 
        onSearch={handleSearch}
      />

      <main className="flex-grow">
        {currentView === 'home' ? (
          <>
            {/* Banner / Hero Section */}
            <Hero />

            {/* Course Categories - Default Gray Background */}
            <section id="categories" className="py-8 md:py-12">
              <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <CategorySection onCategoryClick={handleSearch} />
              </div>
            </section>

            {/* Premium/Recommended Courses - White Background Section */}
            <section id="courses" className="bg-white py-16 md:py-20 relative border-y border-slate-50 shadow-sm">
               {/* Subtle gradient decoration */}
               <div className="absolute top-0 inset-x-0 h-px bg-gradient-to-r from-transparent via-slate-100 to-transparent"></div>
               <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                 <RecommendedCourses />
               </div>
            </section>

            {/* Recommended Institutions - Gray Background with Gradient Accent */}
            <section id="institutions" className="py-16 md:py-20 relative overflow-hidden">
               <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-brand-50/60 via-transparent to-transparent pointer-events-none"></div>
               <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
                 <RecommendedInstitutions />
               </div>
            </section>
          </>
        ) : currentView === 'search-results' ? (
          <SearchResults query={searchQuery} />
        ) : (
          <LearningCenter />
        )}
      </main>

      {/* Footer */}
      <Footer />

      {/* Fixed Right Sidebar */}
      <FloatingSidebar />
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AuthProvider>
      <AppContent />
    </AuthProvider>
  );
};

export default App;

