      {/* Global Login Modal */}
      <LoginModal 
        isOpen={isLoginOpen} 
        onClose={() => setIsLoginOpen(false)} 
        onSuccess={() => {
            setIsLoginOpen(false);
            setCurrentView('learning-center');
        }} 
      />
    </div>
  );
};

