import { defineComponent, ref, onMounted, onUnmounted, computed } from 'vue';
import { Menu, X, Search, LogOut, Store, Sparkles } from 'lucide-vue';
import Logo from './Logo.ts';
import { authStore, authActions } from '../stores/auth';

export default defineComponent({
  components: { Logo, Menu, X, Search, LogOut, Store, Sparkles },
  props: ['currentView'],
  setup(props, { emit }) {
    const isOpen = ref(false);
    const isScrolled = ref(false);
    const showUserMenu = ref(false);
    const searchValue = ref('');
    const isSearchFocused = ref(false);
    const searchHistory = ref(['公考', '机械', '小', '3月5日测试']);

    const user = computed(() => authStore.user);
    const isAuthenticated = computed(() => authStore.isAuthenticated);

    const navLinks = [
      { name: '首页', href: '#', view: 'home' },
      { name: '学习中心', href: '#learning-center', view: 'learning-center' },
      { name: '机构入驻', href: '#institutions', highlight: true, view: 'home' },
      { name: '下载中心', href: '#download', view: 'download' },
      { name: '帮助中心', href: '#', view: 'home' },
    ];

    const handleScroll = () => {
      isScrolled.value = window.scrollY > 10;
    };

    onMounted(() => window.addEventListener('scroll', handleScroll));
    onUnmounted(() => window.removeEventListener('scroll', handleScroll));

    const handleNavClick = (e: any, link: any) => {
      e.preventDefault();
      isOpen.value = false;
      if (link.name === '学习中心') {
        if (!isAuthenticated.value) {
          emit('login-click');
          return;
        }
        emit('navigate', 'learning-center');
      } else if (link.name === '下载中心') {
        emit('navigate', 'download');
      } else {
        emit('navigate', 'home');
      }
    };

    const handleSearchSubmit = () => {
      if (!searchValue.value.trim()) return;
      emit('search', searchValue.value);
      isSearchFocused.value = false;
      if (!searchHistory.value.includes(searchValue.value)) {
        searchHistory.value = [searchValue.value, ...searchHistory.value].slice(0, 8);
      }
    };

    const handleLogout = () => {
        authActions.logout();
        showUserMenu.value = false;
        emit('navigate', 'home');
    };

    return {
      isOpen, isScrolled, showUserMenu, searchValue, isSearchFocused, searchHistory,
      user, isAuthenticated, navLinks,
      handleNavClick, handleSearchSubmit, handleLogout,
      clearHistory: () => searchHistory.value = [],
      removeHistoryItem: (item: string) => searchHistory.value = searchHistory.value.filter(i => i !== item),
      setSearchValue: (val: string) => { searchValue.value = val; handleSearchSubmit(); }
    };
  },
  template: `
  <header :class="['sticky top-0 z-50 transition-all duration-300', isScrolled ? 'bg-white/90 backdrop-blur-md shadow-soft py-2' : 'bg-transparent py-4']">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
      <div class="flex justify-between items-center h-16">
        <div class="flex-shrink-0" @click="$emit('navigate', 'home')">
          <Logo with-text />
        </div>

        <div class="hidden md:flex space-x-1 items-center bg-slate-100/50 p-1 rounded-full px-4">
          <a v-for="link in navLinks" :key="link.name" :href="link.href" @click="handleNavClick($event, link)"
            :class="['font-medium px-4 py-1.5 rounded-full transition-all duration-200 flex items-center', (link.view === currentView && currentView !== 'home') || (link.name === '首页' && currentView === 'home') ? 'text-brand-600 bg-white shadow-sm' : 'text-slate-600 hover:text-brand-600 hover:bg-white', link.highlight ? 'relative gap-2 font-bold group' : '']">
             <span v-if="link.highlight" class="p-1 rounded-full bg-brand-100 text-brand-600 group-hover:bg-brand-500 group-hover:text-white transition-colors">
                <Store :size="14" />
             </span>
             {{ link.name }}
             <span v-if="link.highlight" class="absolute top-0 right-0 -mt-1 -mr-2 bg-rose-500 text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full border-2 border-white shadow-sm transform scale-90 group-hover:scale-105 transition-transform animate-pulse">免费</span>
          </a>
        </div>

        <div class="hidden lg:block flex-1 max-w-xs ml-4 relative">
          <div class="relative group">
            <input type="text" v-model="searchValue" @keydown.enter="handleSearchSubmit" @focus="isSearchFocused = true" @blur="setTimeout(() => isSearchFocused = false, 200)"
              placeholder="请输入课程名称"
              :class="['w-full pl-4 pr-10 py-2 rounded-lg border-2 outline-none transition-all text-sm', isSearchFocused ? 'border-brand-400 bg-white shadow-sm' : 'border-slate-100 bg-slate-50 focus:bg-white focus:border-brand-400']" />
            <Search :class="['w-4 h-4 absolute right-3 top-3 cursor-pointer transition-colors', isSearchFocused ? 'text-brand-500' : 'text-slate-400']" @click.native="handleSearchSubmit" />
          </div>
          <div v-if="isSearchFocused" class="absolute top-full left-0 w-full mt-2 bg-white rounded-xl shadow-xl border border-slate-100 p-4 z-50 animate-fade-in origin-top" @mousedown.prevent>
             <div class="flex justify-between items-center mb-3 text-xs text-slate-400 px-1">
                <span>搜索历史</span>
                <button v-if="searchHistory.length > 0" @click="clearHistory" class="hover:text-slate-600 transition-colors">清空</button>
             </div>
             <div v-if="searchHistory.length > 0" class="space-y-2">
                <div v-for="item in searchHistory" :key="item" class="flex items-center justify-between bg-slate-50 hover:bg-slate-100 rounded-lg px-3 py-2 cursor-pointer group/item transition-colors" @click="setSearchValue(item)">
                    <span class="text-sm text-slate-600">{{ item }}</span>
                    <button @click.stop="removeHistoryItem(item)" class="text-slate-300 hover:text-slate-500 p-1 opacity-0 group-hover/item:opacity-100 transition-opacity"><X :size="14" /></button>
                </div>
             </div>
             <div v-else class="text-center py-4 text-xs text-slate-300">暂无搜索历史</div>
          </div>
        </div>

        <div class="hidden md:flex items-center space-x-3 ml-4">
            <div v-if="isAuthenticated" class="relative">
                <button @click="showUserMenu = !showUserMenu" class="flex items-center gap-2 pl-1 pr-3 py-1 bg-white border border-slate-200 rounded-full hover:shadow-md transition-shadow">
                    <div class="w-8 h-8 rounded-full bg-brand-100 overflow-hidden border border-brand-200"><img :src="user.avatar" alt="User" /></div>
                    <span class="text-sm font-bold text-slate-700 max-w-[80px] truncate">{{ user.username }}</span>
                </button>
                <div v-if="showUserMenu" class="absolute right-0 mt-2 w-48 bg-white rounded-xl shadow-xl border border-slate-100 py-2 animate-scale-in origin-top-right">
                     <div class="px-4 py-2 border-b border-slate-50 mb-1"><p class="text-xs text-slate-400">已登录账号</p><p class="font-bold text-slate-800 truncate">{{ user.username }}</p></div>
                     <button @click="$emit('navigate', 'learning-center'); showUserMenu = false" class="w-full text-left px-4 py-2 text-sm text-slate-600 hover:bg-brand-50 hover:text-brand-600 font-medium">我的学习</button>
                     <div class="border-t border-slate-50 mt-1 pt-1">
                        <button @click="handleLogout" class="w-full text-left px-4 py-2 text-sm text-rose-500 hover:bg-rose-50 font-medium flex items-center gap-2"><LogOut :size="14" /> 退出登录</button>
                     </div>
                </div>
            </div>
            <template v-else>
                <button @click="$emit('login-click')" class="text-slate-600 hover:text-brand-600 font-bold text-sm">登录</button>
                <button @click="$emit('login-click')" class="bg-slate-900 hover:bg-brand-600 text-white px-5 py-2.5 rounded-full text-sm font-bold transition-all shadow-md hover:shadow-lg hover:-translate-y-0.5 flex items-center gap-2">免费注册 <Sparkles class="w-3 h-3 text-accent-400" /></button>
            </template>
        </div>

        <div class="md:hidden flex items-center">
            <button @click="isOpen = !isOpen" class="text-slate-600 hover:text-brand-600 p-2 bg-slate-100 rounded-full">
                <X v-if="isOpen" class="w-6 h-6" />
                <Menu v-else class="w-6 h-6" />
            </button>
        </div>
      </div>
    </div>

    <div v-if="isOpen" class="md:hidden bg-white border-t border-slate-100 absolute w-full shadow-xl rounded-b-3xl">
      <div class="px-6 pt-4 pb-8 space-y-2">
        <a v-for="link in navLinks" :key="link.name" :href="link.href" @click="handleNavClick($event, link)"
            :class="['block px-4 py-3 rounded-2xl text-base font-medium transition-colors', link.highlight ? 'text-brand-600 bg-brand-50 font-bold' : 'text-slate-700 hover:text-brand-600 hover:bg-brand-50']">
             <span v-if="link.highlight" class="inline-block mr-2 text-xs bg-rose-500 text-white px-1.5 rounded">免费</span>
             {{ link.name }}
        </a>
        <div v-if="!isAuthenticated" class="mt-4 pt-4 border-t border-slate-100 flex flex-col space-y-3">
            <button @click="isOpen = false; $emit('login-click')" class="w-full text-center py-3 border-2 border-slate-200 rounded-xl text-slate-600 font-bold">登录</button>
            <button @click="isOpen = false; $emit('login-click')" class="w-full text-center py-3 bg-slate-900 text-white rounded-xl font-bold shadow-lg">立即注册</button>
        </div>
        <button v-else @click="handleLogout" class="w-full text-center py-3 bg-slate-100 text-slate-600 rounded-xl font-bold mt-4">退出登录</button>
      </div>
    </div>
  </header>
  `
});

import { defineComponent, ref, onMounted, onUnmounted, computed } from 'vue';
import { Search, ChevronRight, ChevronLeft, Sparkles, Star, User, ArrowRight } from 'lucide-vue';
import { RECOMMENDED_COURSES } from '../constants';

export default defineComponent({
  components: { Search, ChevronRight, ChevronLeft, Sparkles, Star, User, ArrowRight },
  setup(props, { emit }) {
    const currentSlide = ref(0);
    const searchValue = ref('');
    const isAnimating = ref(false);
    const slides = computed(() => RECOMMENDED_COURSES.slice(0, 5));
    const hotSearchTags = ['Java', 'Python', '考研', '雅思', '公务员'];
    let timer: number | null = null;

    const handleNext = () => {
      isAnimating.value = true;
      setTimeout(() => {
        currentSlide.value = (currentSlide.value + 1) % slides.value.length;
        isAnimating.value = false;
      }, 500);
    };

    const handlePrev = () => {
      isAnimating.value = true;
      setTimeout(() => {
        currentSlide.value = (currentSlide.value - 1 + slides.value.length) % slides.value.length;
        isAnimating.value = false;
      }, 500);
    };

    const startTimer = () => {
      timer = setInterval(handleNext, 6000);
    };

    onMounted(startTimer);
    onUnmounted(() => clearInterval(timer!));

    return {
      currentSlide, searchValue, isAnimating, slides, hotSearchTags,
      currentCourse: computed(() => slides.value[currentSlide.value]),
      handleNext, handlePrev,
      handleSearchSubmit: () => {
        if (searchValue.value.trim()) emit('search', searchValue.value);
      },
      setCurrentSlide: (idx: number) => {
        currentSlide.value = idx;
        clearInterval(timer!);
        startTimer();
      },
      setTag: (tag: string) => emit('search', tag)
    };
  },
  template: `
  <div class="relative pb-16 pt-6"> 
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
      <div class="relative rounded-[2.5rem] overflow-hidden shadow-2xl h-[480px] md:h-[580px] group bg-slate-900 ring-1 ring-slate-900/5 select-none transition-all duration-500">
           <div v-for="(slide, index) in slides" :key="slide.id" :class="['absolute inset-0 transition-opacity duration-700 ease-in-out', index === currentSlide ? 'opacity-100 z-0' : 'opacity-0 -z-10']">
              <img :src="slide.coverImage" :alt="slide.title" class="w-full h-full object-cover" />
              <div v-if="!slide.hideTextOverlay" class="absolute inset-0 bg-gradient-to-r from-slate-900 via-slate-900/80 to-transparent"></div>
              <div v-if="slide.hideTextOverlay" class="absolute inset-0 bg-gradient-to-t from-slate-900/40 via-transparent to-transparent"></div>
           </div>

           <div v-if="!currentCourse.hideTextOverlay" class="absolute inset-0 z-10 flex flex-col justify-center px-8 md:px-16 max-w-3xl">
              <div :class="['transition-all duration-500 transform', isAnimating ? 'opacity-0 translate-y-4' : 'opacity-100 translate-y-0']">
                  <div class="flex items-center gap-3 mb-6">
                      <span class="bg-brand-500 text-white text-xs font-bold px-3 py-1 rounded-full flex items-center gap-1 shadow-lg shadow-brand-500/30 tracking-wide uppercase">
                          <Sparkles :size="12" fill="currentColor" /> {{ currentCourse.tags[0] || "Editor's Choice" }}
                      </span>
                      <div class="h-4 w-px bg-white/20"></div>
                      <span class="text-brand-200 text-sm font-bold tracking-wide">{{ currentCourse.institution }}</span>
                  </div>
                  <h1 class="text-3xl md:text-5xl lg:text-5xl font-black text-white leading-[1.2] mb-6 drop-shadow-md tracking-tight line-clamp-2 max-w-2xl">{{ currentCourse.title }}</h1>
                  <div class="flex flex-wrap items-center gap-6 text-slate-300 mb-8 font-medium text-sm md:text-base">
                      <div class="flex items-center gap-2 bg-white/10 px-3 py-1.5 rounded-full border border-white/5 backdrop-blur-sm">
                          <div class="w-5 h-5 rounded-full bg-white/20 p-0.5"><img :src="\`https://api.dicebear.com/7.x/avataaars/svg?seed=\${currentCourse.instructor}\`" class="w-full h-full rounded-full" /></div>
                          <span class="text-white">{{ currentCourse.instructor }}</span>
                      </div>
                      <div class="flex items-center gap-1.5 text-amber-400"><Star :size="16" fill="currentColor" /><span class="text-white">{{ currentCourse.rating }}</span></div>
                      <div class="flex items-center gap-1.5"><User :size="16" /><span>{{ currentCourse.studentCount }} 人在学</span></div>
                  </div>
                  <div class="flex items-center gap-8">
                      <button class="h-12 md:h-14 px-8 rounded-full bg-white text-slate-900 font-bold text-base md:text-lg flex items-center gap-2 transition-all hover:bg-brand-50 hover:text-brand-600 hover:scale-105 active:scale-95 shadow-xl group/btn">开始学习 <ArrowRight :size="20" class="group-hover/btn:translate-x-1 transition-transform" /></button>
                      <div class="flex flex-col">
                          <div class="flex items-baseline gap-1.5">
                              <span v-if="currentCourse.price === 0" class="text-3xl font-black text-brand-400">免费</span>
                              <template v-else><span class="text-sm font-bold text-white/60">¥</span><span class="text-3xl font-black text-white tracking-tighter">{{ currentCourse.price }}</span></template>
                          </div>
                          <span v-if="currentCourse.originalPrice" class="text-xs text-slate-500 line-through decoration-slate-500/50">原价 ¥{{ currentCourse.originalPrice }}</span>
                      </div>
                  </div>
              </div>
           </div>

           <div v-if="currentCourse.hideTextOverlay" :class="['absolute bottom-8 left-8 md:left-12 z-20 transition-all duration-500', isAnimating ? 'opacity-0 translate-y-4' : 'opacity-100 translate-y-0']">
                <button class="h-10 md:h-12 px-6 rounded-full bg-white/90 backdrop-blur-md text-slate-900 font-bold text-sm md:text-base flex items-center gap-2 transition-all hover:bg-brand-500 hover:text-white shadow-lg hover:shadow-brand-500/30 group/btn">查看详情 <ArrowRight :size="18" class="group-hover/btn:translate-x-1 transition-transform" /></button>
           </div>

           <div class="absolute bottom-8 right-8 flex gap-3 z-20">
              <button @click="handlePrev" class="w-10 h-10 rounded-full border border-white/10 bg-black/20 hover:bg-white hover:text-slate-900 backdrop-blur-md text-white flex items-center justify-center transition-all hover:scale-110 active:scale-95"><ChevronLeft :size="20" /></button>
              <button @click="handleNext" class="w-10 h-10 rounded-full border border-white/10 bg-black/20 hover:bg-white hover:text-slate-900 backdrop-blur-md text-white flex items-center justify-center transition-all hover:scale-110 active:scale-95"><ChevronRight :size="20" /></button>
           </div>

           <div :class="['absolute bottom-10 left-1/2 -translate-x-1/2 md:translate-x-0 flex gap-2 z-20 transition-all duration-500', currentCourse.hideTextOverlay ? 'md:left-auto md:right-36' : 'md:left-16']">
              <button v-for="(slide, idx) in slides" :key="idx" @click="setCurrentSlide(idx)" :class="['h-1 rounded-full transition-all duration-300 shadow-sm', idx === currentSlide ? 'bg-brand-500 w-8' : 'bg-white/40 w-3 hover:bg-white/80']" />
           </div>
      </div>
    </div>

    <div class="absolute bottom-0 left-0 right-0 z-30 px-4 translate-y-1/2 pointer-events-none">
       <div class="max-w-3xl mx-auto pointer-events-auto">
          <div class="bg-white rounded-2xl p-2 shadow-[0_20px_60px_-15px_rgba(0,0,0,0.15)] border border-slate-100 flex items-center gap-2 relative ring-4 ring-white/40 backdrop-blur-xl">
              <div class="flex-1 flex items-center h-12 bg-slate-50 rounded-xl px-4 border border-transparent focus-within:bg-white focus-within:border-brand-200 focus-within:ring-2 focus-within:ring-brand-50 transition-all group">
                  <Search class="text-slate-400 group-focus-within:text-brand-500 mr-3 transition-colors" :size="20" />
                  <input type="text" v-model="searchValue" @keydown.enter="handleSearchSubmit" placeholder="搜索你感兴趣的课程、导师..." class="flex-1 bg-transparent outline-none text-slate-800 font-bold placeholder:text-slate-400/80 placeholder:font-medium h-full w-full text-sm md:text-base" />
              </div>
              <button @click="handleSearchSubmit" class="h-12 px-6 md:px-8 bg-slate-900 hover:bg-brand-600 text-white rounded-xl font-bold text-sm md:text-base transition-all shadow-lg hover:shadow-xl active:scale-95 shrink-0 flex items-center gap-2">搜索</button>
          </div>
          <div class="flex justify-center mt-3 gap-4 text-xs font-medium text-slate-400">
               <button v-for="tag in hotSearchTags" :key="tag" @click="setTag(tag)" class="hover:text-brand-600 transition-colors bg-white/50 px-2 py-0.5 rounded-md hover:bg-white">#{{ tag }}</button>
          </div>
       </div>
    </div>
  </div>
  `
});

