            {isAuthenticated && (
                 <button 
                 onClick={() => {
                     logout();
                     setIsOpen(false);
                     onNavigate('home');
                 }}
                 className="w-full text-center py-3 bg-slate-100 text-slate-600 rounded-xl font-bold mt-4"
             >
                 退出登录
             </button>
            )}
          </div>
        </div>
      )}
    </header>
    </>
  );
};

