                    {/* Form Inputs */}
                    <div className="space-y-4 mb-4">
                        {method === 'password' ? (
                            <>
                                <div className="relative group">
                                    <div className="absolute left-4 top-3.5 text-slate-400 group-focus-within:text-brand-500 transition-colors">
                                        <User size={18} />
