import { defineComponent, ref } from 'vue';
import Navbar from './components/Navbar.js';
import Hero from './components/Hero.js';
import CategorySection from './components/CategorySection.js';
import RecommendedCourses from './components/RecommendedCourses.js';
import RecommendedInstitutions from './components/RecommendedInstitutions.js';
import Footer from './components/Footer.js';
import FloatingSidebar from './components/FloatingSidebar.js';
import LearningCenter from './components/LearningCenter.js';
import SearchResults from './components/SearchResults.js';
import DownloadCenter from './components/DownloadCenter.js';
import MobileTabBar from './components/MobileTabBar.js';
import LoginModal from './components/LoginModal.js';

export default defineComponent({
  components: {
    Navbar, Hero, CategorySection, RecommendedCourses, RecommendedInstitutions,
    Footer, FloatingSidebar, LearningCenter, SearchResults, DownloadCenter,
    MobileTabBar, LoginModal
  },
  setup() {
    const currentView = ref('home');
    const searchQuery = ref('');
    const isLoginOpen = ref(false);

    return {
      currentView, searchQuery, isLoginOpen,
      setCurrentView: (view) => currentView.value = view,
      handleSearch: (query) => {
        searchQuery.value = query;
        currentView.value = 'search-results';
        window.scrollTo({ top: 0, behavior: 'auto' });
      },
      handleLoginClick: () => isLoginOpen.value = true,
      handleLoginSuccess: () => {
        isLoginOpen.value = false;
        currentView.value = 'learning-center';
      }
    };
  },
  template: `
  <div class="min-h-screen flex flex-col relative bg-slate-50 pb-24 md:pb-0">
    <Navbar :current-view="currentView" @navigate="setCurrentView" @search="handleSearch" @login-click="handleLoginClick" />
    <main class="flex-grow">
      <div v-if="currentView === 'home'">
