import Vue from 'vue';

const createIcon = (name, content) => Vue.extend({
  name,
  functional: true,
  props: {
    size: { type: [Number, String], default: 24 },
    color: { type: String, default: 'currentColor' },
    strokeWidth: { type: [Number, String], default: 2 },
    absoluteStrokeWidth: { type: Boolean, default: false }
  },
  render(h, { props, data }) {
    return h('svg', {
      ...data,
      attrs: {
        xmlns: 'http://www.w3.org/2000/svg',
        width: props.size,
        height: props.size,
        viewBox: '0 0 24 24',
        fill: 'none',
        stroke: props.color,
        'stroke-width': props.strokeWidth,
        'stroke-linecap': 'round',
        'stroke-linejoin': 'round',
        ...data.attrs
      },
      domProps: {
        innerHTML: content
      },
      class: [data.class, data.staticClass, 'lucide', `lucide-${name.toLowerCase()}`]
    });
  }
});

