import { computed } from 'vue';
import { Home, Compass, BookOpen, User } from 'lucide-vue-next';
import { authStore } from '../store.js';

export default {
  components: { Home, Compass, BookOpen, User },
  props: ['currentView'],
  emits: ['navigate', 'login'],
  setup(props, { emit }) {
    const isAuthenticated = computed(() => authStore.isAuthenticated);

    const handleStudyClick = () => {
        if (isAuthenticated.value) {
            emit('navigate', 'learning-center');
        } else {
            emit('login');
        }
    };

    const scrollToCategories = () => {
        if (props.currentView !== 'home') {
            emit('navigate', 'home');
            setTimeout(() => document.getElementById('categories')?.scrollIntoView({ behavior: 'smooth' }), 100);
        } else {
            document.getElementById('categories')?.scrollIntoView({ behavior: 'smooth' });
        }
    };

    return {
      isAuthenticated,
      handleStudyClick,
      scrollToCategories
    };
  },
  template: `
    <div class="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 pb-safe pt-2 px-6 shadow-[0_-4px_20px_rgba(0,0,0,0.03)] z-50 h-[84px] flex justify-between items-start">
      <button @click="$emit('navigate', 'home')" :class="['flex flex-col items-center gap-1 w-12', currentView === 'home' ? 'text-brand-600' : 'text-slate-400 hover:text-slate-600']">
        <Home :size="24" :stroke-width="currentView === 'home' ? 2.5 : 2" /><span class="text-[10px] font-bold">首页</span>
      </button>
      <button @click="scrollToCategories" class="flex flex-col items-center gap-1 w-12 text-slate-400 hover:text-slate-600">
        <Compass :size="24" /><span class="text-[10px] font-medium">选课</span>
      </button>
      <div class="relative -top-6">
        <button @click="handleStudyClick" class="w-14 h-14 rounded-full bg-slate-900 text-white flex items-center justify-center shadow-lg shadow-slate-900/30 active:scale-95 transition-transform border-4 border-slate-50"><BookOpen :size="24" /></button>
        <span class="absolute -bottom-5 left-1/2 -translate-x-1/2 text-[10px] font-bold text-slate-600 whitespace-nowrap">学习中心</span>
      </div>
      <button @click="$emit('login')" :class="['flex flex-col items-center gap-1 w-12', currentView === 'learning-center' ? 'text-brand-600' : 'text-slate-400 hover:text-slate-600']">
        <User :size="24" :stroke-width="currentView === 'learning-center' ? 2.5 : 2" /><span class="text-[10px] font-medium">{{ isAuthenticated ? '我的' : '未登录' }}</span>
      </button>
    </div>
  `
};

import { ref, watch } from 'vue';
import { X, User, Lock, Smartphone, ShieldCheck, QrCode, Monitor, ChevronRight, AlertCircle } from 'lucide-vue-next';
import Logo from './Logo.js';
import { login } from '../store.js';

export default {
  components: { Logo, X, User, Lock, Smartphone, ShieldCheck, QrCode, Monitor, ChevronRight, AlertCircle },
  props: ['isOpen'],
  emits: ['close', 'success'],
  setup(props, { emit }) {
    const method = ref('password');
    const isQrMode = ref(false);
    const agreed = ref(false);
    const rememberMe = ref(false);
    const account = ref('');
    const password = ref('');
    const error = ref('');
    const isLoading = ref(false);

    watch(() => props.isOpen, (newVal) => {
      if (newVal) {
        document.body.style.overflow = 'hidden';
        error.value = '';
      } else {
        document.body.style.overflow = 'unset';
      }
    });

    const handleLogin = () => {
      if (!account.value || !password.value) {
        error.value = '请输入账号和密码';
        return;
      }
      if (!agreed.value) {
        error.value = '请先阅读并同意用户协议';
        return;
      }
      isLoading.value = true;
      setTimeout(() => {
        if (account.value === '17549531024' && password.value === '1234@qwer') {
          login(account.value);
          isLoading.value = false;
          emit('close');
          emit('success');
        } else {
          error.value = '账号或密码错误';
          isLoading.value = false;
        }
      }, 800);
    };

    return { method, isQrMode, agreed, rememberMe, account, password, error, isLoading, handleLogin };
  },
  template: `
    <div v-if="isOpen" class="fixed inset-0 z-[100] flex items-center justify-center px-4">
      <div class="absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity" @click="$emit('close')"></div>
      <div class="bg-white rounded-[2rem] shadow-2xl w-full max-w-[420px] relative overflow-hidden animate-scale-in">
        <button @click="$emit('close')" class="absolute top-4 left-4 p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors z-20"><X :size="20" /></button>
        <div class="absolute top-0 right-0 cursor-pointer z-20 group" @click="isQrMode = !isQrMode">
            <div class="w-20 h-20 bg-gradient-to-bl from-brand-50 via-slate-50 to-white absolute top-0 right-0 clip-triangle shadow-sm border-b border-l border-slate-100 group-hover:from-brand-100 transition-colors"></div>
            <div class="absolute top-3 right-3 text-brand-500"><Monitor v-if="isQrMode" :size="28" /><QrCode v-else :size="28" /></div>
        </div>
        <div class="p-8 pt-12">
            <div class="flex justify-center mb-8"><Logo with-text /></div>
            <div v-if="isQrMode" class="flex flex-col items-center py-4 animate-fade-in">
                <h3 class="text-xl font-bold text-slate-800 mb-2">微信扫码登录</h3>
                <p class="text-slate-400 text-sm mb-6">安全快捷 · 无需输入</p>
                <div class="w-48 h-48 border border-slate-100 rounded-2xl p-2 mb-6 shadow-inner bg-slate-50 flex items-center justify-center relative group cursor-pointer">
                    <div class="w-full h-full bg-white rounded-xl flex items-center justify-center overflow-hidden"><img src="https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=MoguoYunkeLogin" alt="QR Code" class="opacity-80 group-hover:opacity-100 transition-opacity" /></div>
                </div>
            </div>
            <div v-else class="animate-fade-in">
                <div class="flex border-b border-slate-100 mb-6">
                    <button :class="['flex-1 pb-3 text-sm font-bold border-b-2 transition-colors', method === 'password' ? 'text-brand-600 border-brand-500' : 'text-slate-400 border-transparent hover:text-slate-600']" @click="method = 'password'">密码登录</button>
                    <button :class="['flex-1 pb-3 text-sm font-bold border-b-2 transition-colors', method === 'sms' ? 'text-brand-600 border-brand-500' : 'text-slate-400 border-transparent hover:text-slate-600']" @click="method = 'sms'">验证码登录</button>
                </div>
                <div v-if="error" class="mb-4 bg-red-50 text-red-500 text-xs font-bold p-3 rounded-xl flex items-center gap-2 animate-pulse"><AlertCircle :size="14" /> {{ error }}</div>
                <div class="space-y-4 mb-4">
                    <template v-if="method === 'password'">
                        <div class="relative group"><div class="absolute left-4 top-3.5 text-slate-400 group-focus-within:text-brand-500 transition-colors"><User :size="18" /></div><input type="text" v-model="account" placeholder="请输入手机号/邮箱/用户名" class="w-full bg-slate-50 border border-slate-200 rounded-xl py-3 pl-11 pr-4 outline-none focus:border-brand-500 focus:bg-white transition-all font-medium text-slate-700" /></div>
                        <div class="relative group"><div class="absolute left-4 top-3.5 text-slate-400 group-focus-within:text-brand-500 transition-colors"><Lock :size="18" /></div><input type="password" v-model="password" placeholder="请输入登录密码" class="w-full bg-slate-50 border border-slate-200 rounded-xl py-3 pl-11 pr-4 outline-none focus:border-brand-500 focus:bg-white transition-all font-medium text-slate-700" /></div>
                    </template>
                    <template v-else>
                        <div class="relative group"><div class="absolute left-4 top-3.5 text-slate-400 group-focus-within:text-brand-500 transition-colors"><Smartphone :size="18" /></div><input type="text" placeholder="请输入手机号" class="w-full bg-slate-50 border border-slate-200 rounded-xl py-3 pl-11 pr-4 outline-none focus:border-brand-500 focus:bg-white transition-all font-medium text-slate-700" /></div>
                    </template>
                </div>
                <button @click="handleLogin" :disabled="isLoading" class="w-full bg-slate-900 hover:bg-brand-600 disabled:bg-slate-300 text-white font-bold py-3.5 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2 group relative">
                    <div v-if="isLoading" class="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                    <template v-else>{{ method === 'password' ? '登录' : '登录 / 注册' }} <ChevronRight :size="18" class="group-hover:translate-x-1 transition-transform" /></template>
                </button>
                <div class="flex items-center justify-center mt-4"><label class="flex items-center gap-2 cursor-pointer group"><input type="checkbox" v-model="agreed" /><span class="text-xs text-slate-400 select-none">已阅读并同意用户协议</span></label></div>
            </div>
        </div>
      </div>
    </div>
  `
};

