    width: props.size || 24,
    height: props.size || 24,
    viewBox: '0 0 24 24',
    fill: 'none',
    stroke: props.color || 'currentColor',
    'stroke-width': props.strokeWidth || 2,
    'stroke-linecap': 'round',
    'stroke-linejoin': 'round',
    class: ['lucide', `lucide-${name.toLowerCase()}`, attrs.class],
    ...attrs, // Transmit other attributes
    innerHTML: content
  });
};

