import { h } from 'vue';

// Helper to create functional component objects directly
const createIcon = (name, content) => ({
  name,
  props: {
    size: { type: [Number, String], default: 24 },
    color: { type: String, default: 'currentColor' },
    strokeWidth: { type: [Number, String], default: 2 },
    absoluteStrokeWidth: { type: Boolean, default: false }
  },
  setup(props, { attrs }) {
    return () => h('svg', {
      xmlns: 'http://www.w3.org/2000/svg',
      width: props.size,
      height: props.size,
      viewBox: '0 0 24 24',
      fill: 'none',
      stroke: props.color,
      'stroke-width': props.strokeWidth,
      'stroke-linecap': 'round',
      'stroke-linejoin': 'round',
      class: ['lucide', `lucide-${name.toLowerCase()}`],
      ...attrs,
      innerHTML: content
    });
  }
});

